/**
 * Unit tests for EmbeddedRungeKuttaIntegrator.integrate
 */
public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen4Test {

    private TestIntegrator integrator;
    private FirstOrderDifferentialEquations equations;

    // Concrete implementation for testing abstract class
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
        private boolean errorEstimationTriggered = false;
        private double forcedError = 0.5;
        private boolean resetManagerReturn = false;

        protected TestIntegrator() {
            super("TestIntegrator", true, 
                new double[]{0.0, 0.5, 1.0}, 
                new double[][]{{0.0, 0.0}, {0.5, 0.0}, {0.0, 1.0}}, 
                new double[]{0.0, 0.5, 1.0}, 
                null, 1e-10, 1e10, 1e-6, 1e-6);
        }

        @Override
        public int getOrder() { return 2; }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            return forcedError;
        }

        public void setForcedError(double error) { this.forcedError = error; }
        public void setResetManagerReturn(boolean val) { this.resetManagerReturn = val; }

        // Mocking internal behavior via overrides if possible, 
        // but since we are testing the logic of the integrate method:
    }

    @Before
    public void setUp() {
        integrator = new TestIntegrator();
        equations = new FirstOrderDifferentialEquations() {
            @Override
            public int getDimension() { return 1; }
            @Override
            public void computeDerivatives(double t, double[] y, double[] yDot) {
                yDot[0] = y[0]; // dy/dt = y -> y = e^t
            }
        };
    }

    @Test
    public void testIntegrate_ForwardIntegration_Success() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 1.0;
        double[] y = new double[1];

        integrator.setForcedError(0.1); // Accept step

        double finalTime = integrator.integrate(equations, t0, y0, t1, y);

        assertEquals(t1, finalTime, 1e-9);
        assertEquals(Math.exp(1.0), y[0], 1e-5);
    }

    @Test
    public void testIntegrate_BackwardIntegration_Success() throws Exception {
        double t0 = 1.0;
        double[] y0 = {Math.exp(1.0)};
        double t1 = 0.0;
        double[] y = new double[1];

        integrator.setForcedError(0.1);

        double finalTime = integrator.integrate(equations, t0, y0, t1, y);

        assertEquals(t1, finalTime, 1e-9);
        assertEquals(1.0, y[0], 1e-5);
    }

    @Test
    public void testIntegrate_RejectStep_DueToError() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.5;
        double[] y = new double[1];

        // First call returns high error, second call returns low error
        // We simulate this by making the error fluctuate
        integrator = new TestIntegrator() {
            private int calls = 0;
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
                calls++;
                return (calls == 1) ? 2.0 : 0.1;
            }
        };

        integrator.integrate(equations, t0, y0, t1, y);
        // If it didn't throw an exception and completed, it handled rejection
    }

    @Test(expected = Math.IllegalArgumentException.class)
    public void testIntegrate_SanityCheck_InvalidDimension() throws Exception {
        double t0 = 0.0;
        double[] y0 = {1.0, 2.0}; // Dimension 2
        double t1 = 1.0;
        double[] y = new double[1]; // Dimension 1
        integrator.integrate(equations, t0, y0, t1, y);
    }

    @Test
    public void testIntegrate_StepHandler_Called() throws Exception {
        StepHandler handler = mock(StepHandler.class);
        integrator.addStepHandler(handler);

        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.5;
        double[] y = new double[1];
        integrator.setForcedError(0.1);

        integrator.integrate(equations, t0, y0, t1, y);

        verify(handler, atLeastOnce()).handleStep(any(), anyBoolean());
    }

    @Test
    public void testIntegrate_WithVectorTolerance() throws Exception {
        double[] absTol = {1e-6};
        double[] relTol = {1e-6};

        TestIntegrator vecIntegrator = new TestIntegrator() {
            @Override
            public int getOrder() { return 2; }
        };
        // Using the constructor with vector tolerances via reflection or a subclass
        // Since we can't easily call protected, we rely on the logic path in the code
        // provided in the prompt where vecAbsoluteTolerance is checked.

        // To trigger the 'else' block in the tolerance calculation:
        // We need an integrator instance where vecAbsoluteTolerance != null
        // This requires using the specific constructor provided in the source.
    }

    @Test
    public void testIntegrate_Fsal_Logic() throws Exception {
        // Test integrator with fsal = true
        TestIntegrator fsalIntegrator = new TestIntegrator() {
            // The fsal is passed to super via constructor
        };
        // The code executes: if (fsal) { System.arraycopy(yDotK[stages - 1], 0, yDotK[0], 0, y0.length); }
        // This is covered by the standard integrate call.
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.1;
        double[] y = new double[1];
        fsalIntegrator.setForcedError(0.1);
        fsalIntegrator.integrate(equations, t0, y0, t1, y);
    }

    @Test
    public void testIntegrate_SmallStep_FilterStep() throws Exception {
        // This test targets the branch where stepSize is very small or zero
        // and the code calls filterStep.
        double t0 = 0.0;
        double[] y0 = {1.0};
        double t1 = 0.1;
        double[] y = new double[1];

        integrator = new TestIntegrator() {
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
                return 0.1;
            }
        };
        // Integration with a very small target time to force small steps
        integrator.integrate(equations, t0, y0, t0 + 1e-15, y);
    }
}

/**
 * Helper class to access protected members if needed, 
 * though in this case we use an anonymous subclass.
 */
class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
    public TestIntegrator() {
        super("Test", true, new double[]{0, 1}, new double[][]{{0}, {1}}, new double[]{0, 1}, 
              null, 1e-10, 1e10, 1e-6, 1e-6);
    }
    @Override public int getOrder() { return 1; }
    @Override protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) { return 0.1; }
}
